mapper.select:
SELECT
COUNT(*) as totalUsers,
SUM(CASE WHEN user_type = '00' THEN 1 ELSE 0 END) as policeCount,
SUM(CASE WHEN user_type = '11' THEN 1 ELSE 0 END) as releasedCount,
SUM(CASE WHEN user_type = '22' THEN 1 ELSE 0 END) as rehabCount,
SUM(CASE WHEN user_type = '33' THEN 1 ELSE 0 END) as otherCount
FROM sys_userinfo u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.dept_id = #{deptId}

SELECT CASE WHEN user_type = '00' THEN '警官' WHEN user_type = '11' THEN '出所人员' WHEN user_type = '22' THEN '社康社戒人员' WHEN user_type = '33' THEN '游客及其他' ELSE '其他' END as name, COUNT(*) as value FROM sys_userinfo u WHERE u.del_flag = '0'
AND DATE(u.create_time) >= #{startDate}
AND DATE(u.create_time) <= #{endDate}
AND u.user_type = #{userType}
AND u.dept_id = #{deptId}
GROUP BY CASE WHEN user_type = '00' THEN '警官' WHEN user_type = '11' THEN '出所人员' WHEN user_type = '22' THEN '社康社戒人员' WHEN user_type = '33' THEN '游客及其他' ELSE '其他' END ORDER BY value DESC

SELECT
DATE_FORMAT(create_time, '%Y-%m-%d') as date,
COUNT(*) as count
FROM sys_userinfo u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.dept_id = #{deptId}

GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY DATE_FORMAT(create_time, '%Y-%m-%d') ASC

SELECT
CONCAT('第', EXTRACT(WEEK FROM create_time), '周') as week,
COUNT(*) as count
FROM sys_userinfo u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.dept_id = #{deptId}

GROUP BY EXTRACT(YEAR FROM create_time), EXTRACT(WEEK FROM create_time)
ORDER BY EXTRACT(YEAR FROM create_time), EXTRACT(WEEK FROM create_time) ASC

SELECT
CONCAT(EXTRACT(YEAR FROM create_time), '年', LPAD(EXTRACT(MONTH FROM create_time)::text, 2, '0'), '月') as month,
COUNT(*) as count
FROM sys_userinfo u
WHERE u.del_flag = '0'

    AND DATE(u.create_time) >= #{startDate}


    AND DATE(u.create_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.dept_id = #{deptId}

GROUP BY EXTRACT(YEAR FROM create_time), EXTRACT(MONTH FROM create_time)
ORDER BY EXTRACT(YEAR FROM create_time), EXTRACT(MONTH FROM create_time) ASC

SELECT
DATE_FORMAT(l.login_time, '%Y-%m-%d') as date,
COUNT(DISTINCT l.user_name) as count
FROM sys_logininfor l
LEFT JOIN sys_userinfo u ON l.user_name = u.user_name
LEFT JOIN sys_dept d ON u.dept_id = d.dept_id
WHERE l.status = '0'

    AND DATE(l.login_time) >= #{startDate}


    AND DATE(l.login_time) <= #{endDate}


    AND u.user_type = #{userType}


    AND u.dept_id = #{deptId}

GROUP BY DATE_FORMAT(l.login_time, '%Y-%m-%d')
ORDER BY DATE_FORMAT(l.login_time, '%Y-%m-%d') ASC
